import yaml

class IRValidatorException(Exception):
    pass

class IRValidator:
    @classmethod
    def validate_from_file(cls, yaml_file=None):
        if yaml_file is None:
            raise ValueError("YAML file path is required")

        try:
            with open(yaml_file, 'r') as file:
                data = yaml.safe_load(file)
        except FileNotFoundError:
            raise FileNotFoundError(f"YAML file {yaml_file} not found")
        except yaml.YAMLError as e:
            raise ValueError(f"Error parsing YAML file: {e}")

        # Assuming the YAML file has a structure where 'required_fields' is a list of required keys
        required_fields = ['field1', 'field2', 'field3']
        missing_fields = [field for field in required_fields if field not in data]

        if missing_fields:
            raise IRValidatorException(f"Missing required fields: {missing_fields}")

        return data
```

